<?php
namespace Tests\Feature;
use App\Models\GuestBookLocation;use App\Models\GuestVisit;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Hash;use Illuminate\Support\Str;use Tests\TestCase;
class GuestBookFlowTest extends TestCase {use RefreshDatabase;public function test_public_guest_can_submit_minimal_form_and_receptionist_checks_out():void{$super=User::factory()->create(['role'=>'superadmin']);$location=GuestBookLocation::create(['name'=>'Resepsionis Utama','public_token'=>(string)Str::uuid(),'created_by'=>$super->id]);$this->get(route('guest-book.public.show',$location->public_token))->assertOk()->assertSee('Keperluan & Tujuan',false);$this->post(route('guest-book.public.store',$location->public_token),['name'=>'Tamu Test','position'=>'Analis','institution'=>'Instansi Test','purpose'=>'Bertemu Bagian Umum','whatsapp'=>'08123456789'])->assertRedirect();$visit=GuestVisit::firstOrFail();$this->assertSame('Tamu Test',$visit->name);$receptionist=User::factory()->create(['role'=>'resepsionis']);$this->actingAs($receptionist)->get(route('dashboard'))->assertRedirect(route('guest-book.index'));$this->get(route('guest-book.index'))->assertOk()->assertSee('Tamu Test')->assertSee('Pilih bidang tujuan')->assertSee('Buku Tamu')->assertDontSee('Daftar Pelatihan');$this->assertNull($visit->target_bidang);$this->put(route('guest-book.target-bidang',$visit),['target_bidang'=>'Sekretariat'])->assertRedirect();$this->assertSame('Sekretariat',$visit->fresh()->target_bidang);$this->put(route('guest-book.checkout',$visit))->assertRedirect();$this->assertNotNull($visit->fresh()->checked_out_at);}
public function test_superadmin_manages_location_qr_exports_and_receptionist_account():void{$super=User::factory()->create(['role'=>'superadmin']);$this->actingAs($super)->post(route('guest-book.locations.store'),['name'=>'Lobby Utama'])->assertRedirect();$location=GuestBookLocation::firstOrFail();$this->get(route('guest-book.qr',$location))->assertOk()->assertHeader('content-type','image/png');$this->post(route('guest-book.accounts.store'),['name'=>'Petugas','username'=>'resepsionis1','whatsapp'=>'0812','password'=>'password123','password_confirmation'=>'password123'])->assertRedirect();$account=User::where('username','resepsionis1')->firstOrFail();$this->assertSame('resepsionis',$account->role);$this->assertTrue(Hash::check('password123',$account->password));$this->get(route('guest-book.export.excel'))->assertOk();$this->get(route('guest-book.accounts'))->assertOk()->assertSee('Akun Pengelola Buku Tamu');$this->get(route('guest-book.export.pdf'))->assertOk()->assertHeader('content-type','application/pdf');}
public function test_other_roles_cannot_access_guest_book_admin():void{$user=User::factory()->create(['role'=>'admin_bidang']);$this->actingAs($user)->get(route('guest-book.index'))->assertForbidden();}}